package com.axplatform.sheet;

import com.axplatform.common.Problem;
import java.math.*;
import java.util.*;

/** Saved data views: source rows are immutable; filters are ANDed before aggregation. */
public final class DataReport {
 private DataReport(){}
 private static final Set<String> OPS=Set.of("EQ","NE","CONTAINS","GT","GTE","LT","LTE","EMPTY","NOT_EMPTY");
 private static final Set<String> AGGS=Set.of("COUNT","SUM","AVG","MIN","MAX","DISTINCT");
 static String str(Map<String,Object> m,String k,String fallback){return Objects.toString(m.get(k),fallback);}
 @SuppressWarnings("unchecked") static List<Map<String,Object>> maps(Map<String,Object> m,String key,int max){Object v=m.getOrDefault(key,List.of());if(!(v instanceof List<?> l)||l.size()>max||l.stream().anyMatch(x->!(x instanceof Map)))throw Problem.invalid(key+": 선택 개수를 확인하세요.");return (List<Map<String,Object>>)v;}
 static List<String> ids(Map<String,Object> m,String key,int max){Object v=m.getOrDefault(key,List.of());if(!(v instanceof List<?> l)||l.size()>max||l.stream().anyMatch(x->!(x instanceof String s)||s.length()>64)||new HashSet<>(l).size()!=l.size())throw Problem.invalid(key+": 중복 없이 항목을 선택하세요.");return l.stream().map(Object::toString).toList();}
 public static Map<String,Object> config(Map<String,Object> raw){
  if(raw==null)throw Problem.invalid("보기 조건을 확인하세요.");
  if(!raw.containsKey("format")){var old=SheetAnalysis.config(raw);var metrics=List.of(Map.of("column",old.get("valueColumn"),"operation",old.get("operation")));raw=new LinkedHashMap<>(Map.of("format","AX_DATA_VIEW_1","mode","REPORT","name",old.get("name"),"sheetId",old.getOrDefault("sheetId","sheet1"),"dimensions",old.get("groupColumn").equals("")?List.of():List.of(old.get("groupColumn")),"metrics",metrics));}
  if(!Set.of("format","mode","name","sheetId","columns","filters","dimensions","metrics","sorts","chart","chartLimit").containsAll(raw.keySet())||!"AX_DATA_VIEW_1".equals(raw.get("format")))throw Problem.invalid("보기 형식을 확인하세요.");
  String mode=str(raw,"mode","TABLE"),name=str(raw,"name","새 보기").strip(),sheet=str(raw,"sheetId","sheet1"),chart=str(raw,"chart","TABLE");
  if(!Set.of("TABLE","REPORT").contains(mode)||!Set.of("TABLE","BAR","LINE","PIE").contains(chart)||name.isEmpty()||name.length()>100||!sheet.matches("[A-Za-z][A-Za-z0-9_-]{0,63}"))throw Problem.invalid("보기 이름·시트·종류를 확인하세요.");
  var filters=new ArrayList<Map<String,Object>>();for(var f:maps(raw,"filters",12)){String col=str(f,"column",""),op=str(f,"operator","EQ"),v=str(f,"value","");if(col.isEmpty()||col.length()>64||!OPS.contains(op)||v.length()>2000||!Set.of("column","operator","value").containsAll(f.keySet()))throw Problem.invalid("조회 조건을 확인하세요.");if(!Set.of("EMPTY","NOT_EMPTY").contains(op)&&v.isEmpty())throw Problem.invalid("조건 값을 입력하세요. 빈 값은 ‘비어 있음’을 선택하세요.");filters.add(Map.of("column",col,"operator",op,"value",v));}
  var metrics=new ArrayList<Map<String,Object>>();for(var m:maps(raw,"metrics",8)){String col=str(m,"column",""),op=str(m,"operation","SUM");if(!AGGS.contains(op)||col.length()>64||(!op.equals("COUNT")&&col.isEmpty())||!Set.of("column","operation").containsAll(m.keySet()))throw Problem.invalid("Y축 집계 열·방식을 확인하세요.");var item=Map.<String,Object>of("column",op.equals("COUNT")?"":col,"operation",op);if(metrics.contains(item))throw Problem.invalid("같은 집계 항목이 중복되었습니다.");metrics.add(item);}
  if(mode.equals("REPORT")&&metrics.isEmpty())throw Problem.invalid("Y축 집계값을 한 개 이상 선택하세요.");
  var sorts=new ArrayList<Map<String,Object>>();for(var s:maps(raw,"sorts",4)){String col=str(s,"column",""),dir=str(s,"direction","asc");if(col.isEmpty()||col.length()>64||!Set.of("asc","desc").contains(dir)||!Set.of("column","direction").containsAll(s.keySet()))throw Problem.invalid("정렬 기준을 확인하세요.");if(sorts.stream().anyMatch(x->col.equals(x.get("column"))))throw Problem.invalid("정렬 열이 중복되었습니다.");sorts.add(Map.of("column",col,"direction",dir));}
  var clean=new LinkedHashMap<String,Object>();clean.put("format","AX_DATA_VIEW_1");clean.put("mode",mode);clean.put("name",name);clean.put("sheetId",sheet);clean.put("chart",chart);Object limit=raw.getOrDefault("chartLimit",20);if(!(limit instanceof Number n)||!Set.of(20,50,100,200).contains(n.intValue())||n.doubleValue()!=n.intValue())throw Problem.invalid("그래프 표시 개수를 확인하세요.");clean.put("chartLimit",((Number)limit).intValue());clean.put("columns",ids(raw,"columns",100));clean.put("dimensions",ids(raw,"dimensions",4));clean.put("metrics",metrics);clean.put("filters",filters);clean.put("sorts",sorts);return clean;
 }
 @SuppressWarnings("unchecked") static List<Map<String,Object>> columns(Map<String,Object> sheet){return (List<Map<String,Object>>)sheet.get("columns");}
 @SuppressWarnings("unchecked") static List<List<String>> rows(Map<String,Object> sheet){return (List<List<String>>)sheet.get("rows");}
 static int index(List<Map<String,Object>> columns,String id){for(int n=0;n<columns.size();n++)if(id.equals(columns.get(n).get("id")))return n;throw Problem.invalid("보기에서 사용한 열 ‘"+id+"’이 없습니다. 원본 열이 변경되었다면 보기 설정을 수정하세요.");}
 static BigDecimal number(String s){try{if(s.isBlank()||ExcelCells.error(s))return null;var n=new BigDecimal(s.replace(",","").strip());return Math.abs((long)n.scale())>100||n.precision()>1000?null:n;}catch(NumberFormatException ex){return null;}}
 static boolean uncertain(Map<String,Object> sheet,int row,int col){String ref=ExcelCells.ref(row+1,col);var meta=ExcelCells.meta(sheet);var paused=ExcelCells.<Map<String,Object>>map(meta,"paused").get(ref);return ExcelCells.map(meta,"issues").containsKey(ref)||paused!=null&&!"USER_INPUT".equals(paused.get("mode"))||ExcelCells.error(rows(sheet).get(row).get(col));}
 public static List<Integer> matching(Map<String,Object> sheet,Map<String,Object> config){
  var cs=columns(sheet);var rows=rows(sheet);var fs=maps(config,"filters",12);var positions=fs.stream().map(f->index(cs,(String)f.get("column"))).toList();var out=new ArrayList<Integer>();
  for(int n=0;n<fs.size();n++){var f=fs.get(n);if(Set.of("GT","GTE","LT","LTE").contains(f.get("operator"))&&"NUMBER".equals(cs.get(positions.get(n)).get("type"))&&number((String)f.get("value"))==null)throw Problem.invalid("숫자 열의 비교 값에는 숫자를 입력하세요.");}
  for(int r=0;r<rows.size();r++){boolean matches=true;for(int n=0;n<fs.size();n++){var f=fs.get(n);int ci=positions.get(n);String v=rows.get(r).get(ci),wanted=(String)f.get("value"),op=(String)f.get("operator");boolean empty=v.isEmpty();int cmp=compare(v,wanted,(String)cs.get(ci).get("type"));boolean pass=switch(op){case "EQ"->v.equals(wanted);case "NE"->!v.equals(wanted);case "CONTAINS"->v.toLowerCase(Locale.ROOT).contains(wanted.toLowerCase(Locale.ROOT));case "EMPTY"->empty;case "NOT_EMPTY"->!empty;case "GT"->!empty&&cmp>0;case "GTE"->!empty&&cmp>=0;case "LT"->!empty&&cmp<0;case "LTE"->!empty&&cmp<=0;default->false;};if(!pass){matches=false;break;}}if(matches)out.add(r);}return out;
 }
 static int compare(String a,String b,String type){if(a.isEmpty()||b.isEmpty())return a.equals(b)?0:a.isEmpty()?1:-1;BigDecimal x=number(a),y=number(b);if("NUMBER".equals(type)&&x!=null&&y!=null)return x.compareTo(y);return a.compareTo(b);}
 static final class Acc {long count,blanks,excluded;BigDecimal sum=BigDecimal.ZERO,min,max;Set<String> distinct=new HashSet<>();void add(String value,boolean bad,boolean distinctOnly){if(bad){excluded++;return;}if(value.isEmpty()){blanks++;return;}distinct.add(value);if(distinctOnly)return;BigDecimal n=number(value);if(n==null){excluded++;return;}count++;sum=sum.add(n);min=min==null?n:min.min(n);max=max==null?n:max.max(n);}String result(String op,long rows){if(op.equals("COUNT"))return Long.toString(rows);if(op.equals("DISTINCT"))return Integer.toString(distinct.size());if(count==0)return "";return (switch(op){case "AVG"->sum.divide(BigDecimal.valueOf(count),12,RoundingMode.HALF_UP);case "MIN"->min;case "MAX"->max;default->sum;}).stripTrailingZeros().toPlainString();}}
 public record Result(Map<String,Object> config,List<Map<String,Object>> columns,List<List<String>> rows,List<Integer> sourceRows,int sourceCount,int matchedCount,long excluded,long blanks) {}
 public static Result build(Map<String,Object> sheet,Map<String,Object> raw){
  var c=config(raw);var source=columns(sheet);var rows=rows(sheet);var matches=matching(sheet,c);var outputCols=new ArrayList<Map<String,Object>>();var output=new ArrayList<List<String>>();var sourceRows=new ArrayList<Integer>();long excluded=0,blanks=0;
  if(c.get("mode").equals("TABLE")){var chosen=ids(c,"columns",100);var indexes=chosen.isEmpty()?java.util.stream.IntStream.range(0,source.size()).boxed().toList():chosen.stream().map(id->index(source,id)).toList();for(int n:indexes)outputCols.add(new LinkedHashMap<>(source.get(n)));for(int r:matches){output.add(indexes.stream().map(i->rows.get(r).get(i)).toList());sourceRows.add(r+2);}}
  else {var dims=ids(c,"dimensions",4);var dimIdx=dims.stream().map(id->index(source,id)).toList();for(int n:dimIdx)outputCols.add(new LinkedHashMap<>(source.get(n)));var ms=maps(c,"metrics",8);var valueIdx=ms.stream().map(m->m.get("operation").equals("COUNT")?-1:index(source,(String)m.get("column"))).toList();
   for(int i=0;i<ms.size();i++){var m=ms.get(i);String op=(String)m.get("operation");String label=op.equals("COUNT")?"행 개수":source.get(valueIdx.get(i)).get("label")+" · "+Map.of("SUM","합계","AVG","평균","MIN","최소","MAX","최대","DISTINCT","고유값 수").get(op);outputCols.add(new LinkedHashMap<>(Map.of("id","metric_"+i,"label",label.length()>100?label.substring(0,100):label,"type","NUMBER","unit",op.equals("COUNT")||op.equals("DISTINCT")?"건":source.get(valueIdx.get(i)).getOrDefault("unit",""),"width",160)));}
   var buckets=new LinkedHashMap<List<String>,Acc[]>();var counts=new LinkedHashMap<List<String>,Long>();
   for(int r:matches){if(dimIdx.stream().anyMatch(i->uncertain(sheet,r,i))){excluded++;continue;}var key=dimIdx.stream().map(i->rows.get(r).get(i)).toList();var a=buckets.computeIfAbsent(key,k->java.util.stream.IntStream.range(0,ms.size()).mapToObj(i->new Acc()).toArray(Acc[]::new));counts.merge(key,1L,Long::sum);for(int i=0;i<ms.size();i++)if(valueIdx.get(i)>=0)a[i].add(rows.get(r).get(valueIdx.get(i)),uncertain(sheet,r,valueIdx.get(i)),ms.get(i).get("operation").equals("DISTINCT"));}
   for(var entry:buckets.entrySet()){var row=new ArrayList<>(entry.getKey());for(int i=0;i<ms.size();i++){var a=entry.getValue()[i];row.add(a.result((String)ms.get(i).get("operation"),counts.get(entry.getKey())));excluded+=a.excluded;blanks+=a.blanks;}output.add(row);sourceRows.add(0);}
  }
  var sorts=maps(c,"sorts",4);var order=new ArrayList<Integer>();for(int n=0;n<output.size();n++)order.add(n);var si=sorts.stream().map(s->index(outputCols,(String)s.get("column"))).toList();order.sort((a,b)->{for(int n=0;n<si.size();n++){int i=si.get(n);String x=output.get(a).get(i),y=output.get(b).get(i);int cmp=compare(x,y,(String)outputCols.get(i).get("type"));if(cmp!=0)return x.isEmpty()||y.isEmpty()?cmp:cmp*(sorts.get(n).get("direction").equals("desc")?-1:1);}return a.compareTo(b);});
  return new Result(c,outputCols,order.stream().map(output::get).toList(),order.stream().map(sourceRows::get).toList(),rows.size(),matches.size(),excluded,blanks);
 }
 public static Map<String,Object> page(Result result,int page,long version){
  int p=Math.max(0,Math.min(page,Math.max(0,(result.rows.size()-1)/100))),start=p*100,end=Math.min(start+100,result.rows.size());var out=new LinkedHashMap<String,Object>();out.put("config",result.config);out.put("columns",result.columns);out.put("rows",result.rows.subList(start,end));out.put("sourceRows",result.sourceRows.subList(start,end));out.put("sourceCount",result.sourceCount);out.put("matchedCount",result.matchedCount);out.put("totalRows",result.rows.size());out.put("excluded",result.excluded);out.put("blanks",result.blanks);out.put("page",p);out.put("pageSize",100);out.put("sheetVersion",version);
  var charts=new ArrayList<String>();charts.add("TABLE");int dimensions=ids(result.config,"dimensions",4).size(),metrics=maps(result.config,"metrics",8).size(),limit=((Number)result.config.get("chartLimit")).intValue();if(result.config.get("mode").equals("REPORT")&&!result.rows.isEmpty()){charts.add("BAR");if(dimensions==1&&result.rows.size()>=2)charts.add("LINE");if(dimensions==1&&metrics==1&&result.rows.size()<=12&&result.rows.stream().allMatch(r->number(r.get(r.size()-1))!=null&&number(r.get(r.size()-1)).signum()>=0)&&result.rows.stream().map(r->number(r.get(r.size()-1))).reduce(BigDecimal.ZERO,BigDecimal::add).signum()>0)charts.add("PIE");}out.put("charts",charts);out.put("chartRows",result.rows.subList(0,Math.min(limit,result.rows.size())));out.put("chartOmitted",Math.max(0,result.rows.size()-limit));return out;
 }
 public static List<Map<String,Object>> profile(Map<String,Object> sheet){var result=new ArrayList<Map<String,Object>>();var cs=columns(sheet);var rows=rows(sheet);for(int ci=0;ci<cs.size();ci++){var c=new LinkedHashMap<>(cs.get(ci));var samples=new LinkedHashSet<String>();int n=0,nonempty=0;for(int r=0;r<rows.size();r++){String v=rows.get(r).get(ci);if(v.isEmpty()||uncertain(sheet,r,ci))continue;nonempty++;if(number(v)!=null)n++;if(samples.size()<8){if(v.length()<=100)samples.add(v);}}c.put("samples",samples);c.put("numeric",!"DATE".equals(c.get("type"))&&nonempty>0&&n==nonempty);result.add(c);}return result;}
}
